WITH with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS session_start_flag FROM transactions), islands AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, SUM(session_start_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT id, account_id, txn_type, amount, txn_time, merchant FROM islands ORDER BY account_id DESC, txn_type DESC;
